const EMAIL_CORE = "[A-Za-z0-9._%+-]+@(?:[A-Za-z0-9-]+\\.)+[A-Za-z]{2,}";
const TOKEN_EMAIL_RE = new RegExp("(<)?(" + EMAIL_CORE + ")(>)?([,.;:]?)", "i");
